import { useState } from "react";

import "./UserBoxs.css";

function UserBoxs({ key, name, username, email, phone, website }) {
  const [info, setInfo] = useState(false);

  const openClose = () => {
    setInfo(!info);
  };
  return (
    <div key={key} className="mainBoxes">
      <h2>{name}</h2>
      <h4>#{username}</h4>
      <button className="contactBtn" onClick={openClose}>
        Contact me
      </button>
      <div className={info ? 'infoDiv' : 'invisible'}>
        <p>Email: {email}</p>
        <p>Phone: {phone}</p>
        <p>Webpage: {website}</p>
      </div>
    </div>
  );
}

export default UserBoxs;
